-- Essais jetables après fixtures, 0089 puis proposition 0090 ; aucune action conservée.
BEGIN;
CREATE FUNCTION pg_temp.assert_true(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'ECHEC : %',label; END IF; RAISE NOTICE 'OK : %',label; END $$;
CREATE FUNCTION pg_temp.reject(q text,expected text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN
 BEGIN EXECUTE q; EXCEPTION WHEN OTHERS THEN IF position(expected in SQLERRM)>0 THEN RAISE NOTICE 'OK refus : %',expected; RETURN; ELSE RAISE; END IF; END;
 RAISE EXCEPTION 'Action acceptée à tort : %',expected;
END $$;
SELECT set_config('test.uid','10000000-0000-0000-0000-000000000001',true);
SELECT pg_temp.assert_true(jsonb_array_length(public.furnishing_state_v2()->'homes')=3,'Deux propriétés et une location active seulement');
SELECT pg_temp.assert_true((SELECT (h->>'rooms')::integer=2 FROM jsonb_array_elements(public.furnishing_state_v2()->'homes') h WHERE h->>'kind'='location'),'Pièces connues conservées');
SELECT public.rental_furnishing_save('40000000-0000-0000-0000-000000000001',0,'["Salon","Chambre"]','[{"asset_id":"30000000-0000-0000-0000-000000000001","room":0,"x":1,"y":1,"rotation":90}]','50000000-0000-0000-0000-000000000001');
SELECT pg_temp.assert_true((public.rental_furnishing_save('40000000-0000-0000-0000-000000000001',0,'["Salon","Chambre"]','[{"asset_id":"30000000-0000-0000-0000-000000000001","room":0,"x":1,"y":1,"rotation":90}]','50000000-0000-0000-0000-000000000001')->>'already')::boolean,'Sauvegarde répétée sans nouvel effet');
SELECT pg_temp.assert_true((SELECT h->>'version'='1' AND h->'room_names'='["Salon","Chambre"]'::jsonb AND jsonb_array_length(h->'placements')=1 FROM jsonb_array_elements(public.furnishing_state_v2()->'homes') h WHERE h->>'kind'='location'),'Relecture des pièces et placements');
SELECT pg_temp.assert_true((SELECT f->>'placed_home'='rental:40000000-0000-0000-0000-000000000001' FROM jsonb_array_elements(public.furnishing_state_v2()->'furniture') f WHERE f->>'asset_id'='30000000-0000-0000-0000-000000000001'),'Inventaire identifie la location');
SELECT pg_temp.reject($q$SELECT public.home_furnishing_save('20000000-0000-0000-0000-000000000001',0,'["A","B"]','[{"asset_id":"30000000-0000-0000-0000-000000000001","room":0,"x":0,"y":0,"rotation":0}]','60000000-0000-0000-0000-000000000001')$q$,'Objet placé dans une location');
SELECT pg_temp.reject($q$SELECT public.rental_furnishing_save('40000000-0000-0000-0000-000000000001',0,'["A","B"]','[]','60000000-0000-0000-0000-000000000002')$q$,'Aménagement modifié ailleurs');
SELECT pg_temp.reject($q$SELECT public.rental_furnishing_save('40000000-0000-0000-0000-000000000001',1,'["A","B"]','[{"asset_id":"30000000-0000-0000-0000-000000000003","room":0,"x":0,"y":0,"rotation":0}]','60000000-0000-0000-0000-000000000003')$q$,'Objet non possédé');
SELECT pg_temp.reject($q$SELECT public.rental_furnishing_save('40000000-0000-0000-0000-000000000001',1,'["A","B"]','[{"asset_id":"30000000-0000-0000-0000-000000000001","room":0,"x":0,"y":0,"rotation":0},{"asset_id":"30000000-0000-0000-0000-000000000002","room":0,"x":0,"y":0,"rotation":0}]','60000000-0000-0000-0000-000000000004')$q$,'Objets superposés');
SELECT pg_temp.reject($q$SELECT public.rental_furnishing_save('40000000-0000-0000-0000-000000000001',1,'["A","B"]','[{"asset_id":"30000000-0000-0000-0000-000000000001","room":0,"x":7,"y":7,"rotation":0}]','60000000-0000-0000-0000-000000000005')$q$,'Objet hors de la pièce');
SELECT pg_temp.reject($q$SELECT public.rental_furnishing_save('40000000-0000-0000-0000-000000000002',0,'["A"]','[]','60000000-0000-0000-0000-000000000006')$q$,'Location non active ou non autorisée');
SELECT set_config('test.uid','10000000-0000-0000-0000-000000000002',true);
SELECT pg_temp.assert_true((SELECT h->>'rooms'='1' FROM jsonb_array_elements(public.furnishing_state_v2()->'homes') h WHERE h->>'kind'='location'),'Un espace générique sans pièces connues');
SET LOCAL ROLE authenticated;
SELECT pg_temp.assert_true((SELECT count(*)=0 FROM public.rental_home_layouts),'Un autre joueur ne lit pas les pièces privées');
SELECT pg_temp.assert_true((SELECT count(*)=0 FROM public.rental_home_placements),'Un autre joueur ne lit pas les placements privés');
SELECT pg_temp.assert_true((SELECT count(*)=0 FROM public.rental_home_save_operations),'Un autre joueur ne lit pas les opérations privées');
RESET ROLE;
SELECT set_config('test.uid','10000000-0000-0000-0000-000000000001',true);
SELECT public.rental_furnishing_save('40000000-0000-0000-0000-000000000001',1,'["Salon","Chambre"]','[]','60000000-0000-0000-0000-000000000007');
SELECT public.home_furnishing_save('20000000-0000-0000-0000-000000000001',0,'["A","B"]','[{"asset_id":"30000000-0000-0000-0000-000000000001","room":0,"x":0,"y":0,"rotation":0}]','60000000-0000-0000-0000-000000000008');
SELECT pg_temp.reject($q$SELECT public.rental_furnishing_save('40000000-0000-0000-0000-000000000001',2,'["A","B"]','[{"asset_id":"30000000-0000-0000-0000-000000000001","room":0,"x":0,"y":0,"rotation":0}]','60000000-0000-0000-0000-000000000009')$q$,'Objet placé dans un autre logement');
SELECT public.home_furnishing_save('20000000-0000-0000-0000-000000000001',1,'["A","B"]','[]','60000000-0000-0000-0000-000000000010');
SELECT public.rental_furnishing_save('40000000-0000-0000-0000-000000000001',2,'["Salon","Chambre"]','[{"asset_id":"30000000-0000-0000-0000-000000000001","room":0,"x":0,"y":0,"rotation":0}]','60000000-0000-0000-0000-000000000011');
UPDATE public.housing_leases SET status='terminé',ended_at=now() WHERE id='40000000-0000-0000-0000-000000000001';
SELECT pg_temp.reject($q$SELECT public.rental_furnishing_save('40000000-0000-0000-0000-000000000001',3,'["A","B"]','[]','60000000-0000-0000-0000-000000000012')$q$,'Location non active ou non autorisée');
SELECT pg_temp.assert_true(jsonb_array_length(public.furnishing_state_v2()->'homes')=2,'Location terminée absente');
SELECT pg_temp.assert_true((SELECT f->'placed_home'='null'::jsonb FROM jsonb_array_elements(public.furnishing_state_v2()->'furniture') f WHERE f->>'asset_id'='30000000-0000-0000-0000-000000000001'),'Meuble conservé et disponible après fin de bail');
SET LOCAL ROLE authenticated;
SELECT pg_temp.assert_true((SELECT count(*)=0 FROM public.rental_home_layouts),'Ancien locataire ne lit plus son aménagement');
RESET ROLE;
INSERT INTO public.housing_leases VALUES('40000000-0000-0000-0000-000000000003','00000000-0000-0000-0000-000000000001','home','location','actif',null,'Nouvelle location',700,700);
SELECT pg_temp.assert_true((SELECT h->>'version'='0' AND jsonb_array_length(h->'placements')=0 FROM jsonb_array_elements(public.furnishing_state_v2()->'homes') h WHERE h->>'kind'='location'),'Nouveau bail : aménagement neuf');
SELECT public.rental_furnishing_save('40000000-0000-0000-0000-000000000003',0,'["Neuf","Chambre"]','[{"asset_id":"30000000-0000-0000-0000-000000000001","room":0,"x":0,"y":0,"rotation":0}]','60000000-0000-0000-0000-000000000013');
SELECT pg_temp.assert_true((SELECT count(*)=1 FROM public.rental_home_placements),'Un seul placement après réutilisation du meuble');
SELECT pg_temp.assert_true((SELECT sum(purchase_price)=150887 FROM public.personal_assets),'Patrimoine inchangé');
SELECT pg_temp.assert_true((SELECT bool_and(monthly IN(300,700) AND deposit=monthly) FROM public.housing_leases),'Loyers et dépôts inchangés');
SELECT set_config('test.uid','',true);
SELECT pg_temp.reject('SELECT public.furnishing_state_v2()','Non connecté');
ROLLBACK;